package com.lbos.commercecustomer.service;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lbos.commercecustomer.dto.client.partner.RetailerContextResponse;import com.lbos.commercecustomer.dto.request.ProductRequest;import com.lbos.commercecustomer.entity.*;import com.lbos.commercecustomer.enums.InventoryStatus;import com.lbos.commercecustomer.enums.ProductStatus;import com.lbos.commercecustomer.exception.*;import com.lbos.commercecustomer.mapper.CommerceMapper;import com.lbos.commercecustomer.repository.*;import com.lbos.commercecustomer.service.impl.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;class CatalogueServiceImplTest{ProductRepository r=mock(ProductRepository.class);ProductCategoryRepository c=mock(ProductCategoryRepository.class);ContextSupport x=mock(ContextSupport.class);CatalogueServiceImpl s;@BeforeEach void init(){when(x.retailer()).thenReturn(new RetailerContextResponse(UUID.randomUUID(),UUID.randomUUID(),"R",UUID.randomUUID()));s=new CatalogueServiceImpl(r,c,mock(CustomerWishlistItemRepository.class),mock(CustomerCartRepository.class),mock(CustomerReviewRepository.class),x,new CommerceMapper());}@Test void skuNormalized(){var cat=new ProductCategory();cat.setId(1L);cat.setName("Food");when(c.findById(1L)).thenReturn(Optional.of(cat));when(r.save(any())).thenAnswer(a->{Product p=a.getArgument(0);p.setId(1L);return p;});var out=s.create(new ProductRequest("Rice","rice-1",1L,new BigDecimal("10.00"),10,ProductStatus.ACTIVE,"Long description",null));assertEquals("RICE-1",out.sku());}@Test void lowStockBoundary(){assertEquals(InventoryStatus.LOW_STOCK,new CommerceMapper().inventory(10,null));assertEquals(InventoryStatus.HEALTHY,new CommerceMapper().inventory(11,null));assertEquals(InventoryStatus.OUT_OF_STOCK,new CommerceMapper().inventory(0,null));}}